#include "bridge.hpp"
#include "../../code_tools/source/config.hpp"
#include "engine.hpp"

namespace blitz::lsp::bridge {
	std::string tidy_text(std::string const& source, std::filesystem::path const& file, std::filesystem::path const& userlibs_dir, bool& ok)
	{
		ok = false;
		blitz::tidy::config cfg;
		auto dir = file.has_parent_path() ? file.parent_path() : std::filesystem::path(".");
		if (auto config = tools::find_config(dir, { ".blitz-tidy", "blitz-tidy.json" })) {
			cfg.apply(tools::load_config(*config));
		}
		cfg.file = file;
		if (cfg.userlibs_dir.empty()) cfg.userlibs_dir = userlibs_dir;
		auto result = blitz::tidy::run(source, cfg);
		ok = !result.failed;
		return result.text;
	}
} // namespace blitz::lsp::bridge
